-- ===================================================================
-- PhoneShop BD Demo Data Seed
-- ===================================================================
-- Based on current models from gadgetandgear.com (Bangladesh)
-- Includes:
--   • 30+ phone models across 8 brands
--   • Multiple variants per model (color/storage)
--   • 4-10 phone units per model in inventory (with valid IMEI)
--   • ~80 sales spread over 3 months
--   • Baki (credit) and cash transactions
--   • Cash book entries
-- ===================================================================

-- === STEP 1: CLEAR ALL EXISTING DEMO DATA ===
TRUNCATE TABLE public.order_items CASCADE;
TRUNCATE TABLE public.orders CASCADE;
TRUNCATE TABLE public.cash_transaction_edits CASCADE;
TRUNCATE TABLE public.cash_transactions CASCADE;
TRUNCATE public.phones CASCADE;
DELETE FROM public.products WHERE id IS NOT NULL;
DELETE FROM public.site_settings WHERE id <> 1 OR id IS NULL;

-- === STEP 2: ADD NEW BRANDS ===
ON CONFLICT (slug) DO NOTHING;

